    AssertGitBlob 'COMMITTED_AUTHORITY' $Context 'git_blob_identity' $Observed.git_blob_identity;AssertGitBlob 'COMMITTED_AUTHORITY' $Context 'raw_worktree_blob_identity' $Observed.raw_worktree_blob_identity;AssertGitBlob 'COMMITTED_AUTHORITY' $Context 'clean_filtered_worktree_blob_identity' $Observed.clean_filtered_worktree_blob_identity;AssertKind 'COMMITTED_AUTHORITY' $Context 'mode' $Observed.mode 'STRING';AssertKind 'COMMITTED_AUTHORITY' $Context 'path' $Observed.path 'STRING';AssertSha256 'COMMITTED_AUTHORITY' $Context 'raw_sha256' $Observed.raw_sha256;AssertKind 'COMMITTED_AUTHORITY' $Context 'size' $Observed.size 'INTEGER';if(-not(TestExactCheckoutIdentityRecord $Observed ([bool]$CandidateWorktree))-or-not[bool]$Observed.compiler_input_authority-or[string]$Observed.rejection_reason-cne''){Fail 'EXACT_CHECKOUT_IDENTITY_INVALID' $Context}
